INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.89.0',
  '2026-09-17',
  'Пульт ТВ: фото и видеоролики',
  E'В медиатеке на приставке два новых раздела — «Фото» и «Видеоролики». Пока в разделе ничего нет, его не видно.\n\n«Фото» — это альбомы: плитка на папку с обложкой из первого снимка. В альбоме снимок занимает большую часть экрана, а внизу полоса — сами снимки и вложенные папки. Стрелками ходите по полосе, и снимок сверху сразу меняется. OK — снимок во весь экран, там стрелки листают дальше по кругу, «Назад» возвращает к полосе на том же снимке. Приставке уходят уменьшенные под экран копии, поэтому даже семьдесят снимков по 7 МБ листаются без ожидания.\n\n«Видеоролики» — домашнее видео: ролик своей плиткой или папка с роликами, которые идут подряд. Постеры для роликов в интернете не ищутся — по имени домашнего файла нашлась бы чужая картинка; если положить картинку с тем же именем рядом, она покажется.\n\nПервым альбомом загружена свадьба Вероники и Андрея.',
  E'Медиаагент: новые виды библиотек photo и clips (clip — синоним). photos.go — GET /api/photos?id= (снимки папки и вложенные папки со снимками, с обложками) и GET /photo/{id}?k=&s=thumb|view. Копии собираются стандартной библиотекой Go без внешних программ: разбор JPEG, уменьшение усреднением прямо в плоскостях YCbCr (в RGB переводится только результат), поворот по EXIF-метке 0x0112 (свой разбор APP1, все 8 значений), превью до 480 px и экранная до 1920×1080 (рамка для повёрнутого кадра меняется местами) за один разбор. Кэш MEDIA_CACHE/photos, ключ — путь+размер+время правки; в ссылке &v=время правки, поэтому Cache-Control immutable на 30 дней. Две сборки разом (семафор), своя блокировка на снимок; открытие папки запускает фоновый прогрев её снимков по одному (не чаще раза в 10 минут на папку). WebP и GIF отдаются как есть (GIF потерял бы анимацию). Замер на i3-6100U: ~1,0 с на снимок 24 Мп (ImageMagick на той же машине — 1,0 с), 75 снимков — 75 с; превью ~20 КБ, экранная ~200 КБ.\n\nКаталог: clipTiles — ролик из корня плиткой clip, папка с роликами на любой глубине — плиткой clips; постер только если картинка уже лежит рядом. poster() теперь ищет в интернете только для библиотек вида video (libraryOf — самая глубокая подходящая библиотека): туда же приходит «Продолжить просмотр» ролика. photoTiles — папки первого уровня со снимками (рекурсивно до 6 уровней), снимки в корне — плиткой с названием библиотеки.\n\nСтраница: экран папки фото (#visual.photos: снимок flex:1, полоса превью 88 px), снимок меняется по focusin в полосе (превью сразу, экранная копия через 150 мс тишины и подменяется только после загрузки), #pfull — во весь экран, стрелки перехватываются до пространственной навигации, «Назад»/Escape/OK и habitsBack() закрывают. Экран папки роликов — как у музыки, воспроизведение через startSeason. Пустые «Видеоролики» и «Фото» на главной не выводятся.\n\nsend-photos.py: ZIP одним потоком cat по SSH (26 МБ/с), распаковка на сервере python3 во временную скрытую папку и os.rename на место (или --merge), список файлов — отдельным файлом (предел длины аргумента 128 КБ), мусор архиваторов пропускается, «../» не выпускается за альбом. В конце /api/catalog + /api/photos для прогрева.\n\nПроверено: photos_test.go (EXIF в обоих порядках байт, 8 поворотов на картинке 3×2, вписывание в рамку, повёрнутый кадр → 720×1080, цвет при уменьшении), локальный агент в браузере (разделы, скрытие пустых, стрелки по полосе, во весь экран и обратно на том же снимке, вложенная папка и «Назад», ролики папкой и одиночные, 404 постера ролика без запроса в интернет, раскладка 960×540 — снимок 363 px), выкладка на res-i3 и загрузка свадьбы (75 снимков: передача 16 с, распаковка 4 с).'
);
